tests:
test('counts vowels in a word', () => { assert.equal(countVowels('banana'), 3); });
test('ignores case', () => { assert.equal(countVowels('AEIOU'), 5); });
test('counts across a sentence', () => { assert.equal(countVowels('Hello World'), 3); });
test('no vowels gives 0', () => { assert.equal(countVowels('rhythm'), 0); });
test('empty string gives 0', () => { assert.equal(countVowels(''), 0); });

referenceSolution:
function countVowels(text) {
  const vowels = 'aeiou';
  let count = 0;
  for (const character of text.toLowerCase()) {
    if (vowels.includes(character)) {
      count += 1;
    }
  }
  return count;
}
